pA = (0, 0);
pB = pA + dir(300);
pC = pA + dir(240);
pD = pC + dir(270);
pE = pB + dir(270);
draw(pA--pB--pC--pA);
draw(pB--pC--pD--pE--pB);
draw(pD--pA--pE, red);
label("$A$", pA, N);
label("$B$", pB, E);
label("$C$", pC, W);
label("$D$", pD, SW);
label("$E$", pE, SE);
